package main

// Preview: read an import file, resolve its column mapping and render the SQL
// that ImportFile would run — without touching the database. It is the same
// wiring as ImportFile minus the transaction and the writes, so the preview
// cannot drift from the run.

import (
	"context"
	"fmt"
	"os"
	"strings"

	"github.com/dbcore/dbcore"

	"tablepro-go/internal/importfile"
)

// previewSampleRows is how many rows the sample INSERT statements show. The
// full batch is generated by ImportFile; the preview only needs the shape.
const previewSampleRows = 5

// ImportPreview is the read-only preview of one import request.
type ImportPreview struct {
	Format string               `json:"format,omitempty"`
	Paths  []string             `json:"paths,omitempty"`
	Tables []ImportTablePreview `json:"tables"`
	Notes  []string             `json:"notes,omitempty"`
	SQL    []string             `json:"sql,omitempty"`
}

// ImportTablePreview is the preview of one (file, sheet) → table work unit.
type ImportTablePreview struct {
	Path          string                 `json:"path,omitempty"`
	Sheet         string                 `json:"sheet,omitempty"`
	Table         string                 `json:"table"`
	Exists        bool                   `json:"exists"`
	Columns       []string               `json:"columns"`
	TargetColumns []string               `json:"targetColumns,omitempty"`
	Mapped        []importfile.ColumnMap `json:"mapped,omitempty"`
	DDL           string                 `json:"ddl,omitempty"`
	Sample        []string               `json:"sample,omitempty"`
	Rows          int                    `json:"rows"`
	Notes         []string               `json:"notes,omitempty"`
}

// PreviewImport parses the request and renders the SQL without writing.
func (a *App) PreviewImport(req ImportRequest) (ImportPreview, error) {
	pv := ImportPreview{}
	opts := importfile.Normalize(importfile.Options{
		Format:     req.Options.Format,
		HasHeader:  req.Options.HasHeader,
		Delimiter:  req.Options.Delimiter,
		InferTypes: req.Options.InferTypes,
		Mode:       req.Options.Mode,
		UpsertKeys: req.Options.UpsertKeys,
	}, requestPath(req))
	if opts.Format == "sql" {
		return pv, fmt.Errorf("import: SQL 脚本按语句顺序执行，没有可预览的表结构")
	}
	pv.Format = opts.Format
	if len(req.Paths) > 0 {
		pv.Paths = req.Paths
	} else if req.Path != "" {
		pv.Paths = []string{req.Path}
	}

	conn, err := a.connection(req.ConnID)
	if err != nil {
		return pv, err
	}
	drv, err := a.execDriver(conn, req.Database)
	if err != nil {
		return pv, err
	}
	schema := req.Schema
	if schema == "" {
		schema = importSchema(conn.Type, req.Database)
	}
	jobs, err := buildImportJobs(req, opts)
	if err != nil {
		return pv, err
	}
	ctx, done := a.beginRunIn(context.Background(), req.ConnID, "import-preview")
	defer done()

	for _, job := range jobs {
		tp, err := a.previewJob(ctx, conn, drv, schema, req, opts, job)
		if err != nil {
			// One unusable unit is reported on its own entry, not fatal: a
			// multi-sheet workbook can still show the sheets that do resolve.
			tp = ImportTablePreview{Path: job.path, Sheet: job.sheet, Table: job.table, Notes: []string{err.Error()}}
		}
		pv.Tables = append(pv.Tables, tp)
	}
	if len(req.Sheets) == 0 && opts.Format == "xlsx" && len(pv.Tables) > 1 {
		pv.Notes = append(pv.Notes, fmt.Sprintf(
			"工作簿有 %d 个工作表，将分别写入 %d 张表（每个工作表一个独立事务，单个失败不影响其他表）。",
			len(pv.Tables), len(pv.Tables)))
	}
	for _, t := range pv.Tables {
		pv.SQL = append(pv.SQL, t.DDL)
		pv.SQL = append(pv.SQL, t.Sample...)
	}
	return pv, nil
}

// previewJob renders one work unit.
func (a *App) previewJob(ctx context.Context, conn *Connection, drv dbcore.SQLDriver, schema string, req ImportRequest, opts importfile.Options, job importJob) (ImportTablePreview, error) {
	tp := ImportTablePreview{Path: job.path, Sheet: job.sheet, Table: job.table}
	if job.table == "" {
		return tp, fmt.Errorf("目标表名不能为空")
	}
	cols, rows, err := previewLoad(job, opts)
	if err != nil {
		return tp, err
	}
	if len(cols) == 0 {
		return tp, fmt.Errorf("文件没有可识别的列")
	}
	tp.Columns = cols
	tp.Rows = len(rows)

	// Resolving the mapping reads the target table's catalog; nothing is
	// written.
	resolved, keep, mapped, exists, err := previewResolve(ctx, drv, schema, job.table, opts, req, cols)
	if err != nil {
		return tp, err
	}
	tp.Exists = exists
	tp.Mapped = mapped
	tp.Notes = append(tp.Notes, mappingNotes(cols, mapped, keep, req)...)
	// The dialog's mapping editor needs the table's own columns; they are read
	// here (no write) and reported alongside the auto-matched pairing. The
	// catalog is probed whether or not a mapping was supplied, so an explicit
	// mapping still shows the table it targets.
	if tc, cerr := importTableColumns(ctx, drv, schema, job.table); cerr == nil {
		tp.TargetColumns = tc
	}

	sample := rows
	if len(sample) > previewSampleRows {
		sample = sample[:previewSampleRows]
	}
	sampleRows := sample
	if keep != nil {
		sampleRows = projectRows(sample, keep)
	}
	if req.Options.CreateTable && !exists {
		kinds := make([]string, len(resolved))
		for i := range kinds {
			kinds[i] = "text"
		}
		if opts.InferTypes {
			kinds = importfile.InferTypes(resolved, sampleRows)
		}
		tp.DDL = importfile.CreateTableSQL(conn.Type, schema, job.table, resolved, kinds)
		tp.Notes = append(tp.Notes, fmt.Sprintf("表 %s 不存在，将创建。", job.table))
	} else if exists {
		tp.Notes = append(tp.Notes, fmt.Sprintf("表 %s 已存在，按上述映射写入。", job.table))
	}

	upsert := opts
	if opts.Mode == "upsert" {
		keys, kerr := a.resolveUpsertKeys(ctx, drv, conn.Type, schema, job.table, resolved, opts.UpsertKeys)
		if kerr != nil {
			tp.Notes = append(tp.Notes, "upsert 键解析失败，预览的 INSERT 仅示意："+kerr.Error())
		} else {
			upsert.UpsertKeys = keys
		}
	}
	if len(sampleRows) > 0 {
		stmt, _, serr := importfile.InsertSQL(conn.Type, schema, job.table, resolved, sampleRows, upsert)
		if serr != nil {
			tp.Notes = append(tp.Notes, "生成示例 INSERT 失败："+serr.Error())
		} else {
			tp.Sample = append(tp.Sample, stmt)
		}
	} else {
		tp.Notes = append(tp.Notes, "该工作表没有数据行，只会执行建表/写入语句结构。")
	}
	return tp, nil
}

// previewLoad parses one job's file into (cols, rows) without a database.
func previewLoad(job importJob, opts importfile.Options) ([]string, [][]*string, error) {
	if job.data != nil {
		return job.data.Cols, job.data.Rows, nil
	}
	f, err := os.Open(job.path)
	if err != nil {
		return nil, nil, err
	}
	defer f.Close()
	switch opts.Format {
	case "json":
		return importfile.ParseJSON(importfile.DecodingReader(f))
	case "xlsx":
		// XLSX jobs always carry pre-parsed worksheet data; reaching here means a
		// new job type forgot to set it, and reading the zip as CSV would silently
		// produce garbage rather than fail.
		return nil, nil, fmt.Errorf("import: Excel 工作簿需要预解析的工作表数据")
	default:
		return importfile.ParseCSV(importfile.DecodingReader(f), opts)
	}
}

// previewResolve applies the mapping rules exactly as ImportFile would: an
// explicit mapping is authoritative and applied before any table is created,
// otherwise the file columns are auto-matched against an existing table's
// catalog. It returns the target columns, the matching file indexes, the
// reported mapping, and whether the table exists.
func previewResolve(ctx context.Context, drv dbcore.SQLDriver, schema, table string, opts importfile.Options, req ImportRequest, fileCols []string) (cols []string, keep []int, mapped []importfile.ColumnMap, exists bool, err error) {
	specs, authoritative, err := explicitColumnSpecs(req, fileCols)
	if err != nil {
		return nil, nil, nil, false, err
	}
	// The target table's catalog is read first so `exists` is true even on the
	// authoritative path; a mapping can only target a table that is there.
	tableCols, err := importTableColumns(ctx, drv, schema, table)
	if err != nil {
		return nil, nil, nil, false, err
	}
	exists = len(tableCols) > 0
	if authoritative {
		resolved, idx := importfile.BuildColumnMap(specs, fileCols)
		if len(resolved) == 0 {
			return nil, nil, nil, false, fmt.Errorf("映射后没有可导入的列")
		}
		return resolved, idx, importfile.MappedColumns(specs, fileCols), exists, nil
	}
	if exists {
		mapping := importfile.MatchColumns(fileCols, tableCols, opts.HasHeader)
		importfile.DropSources(mapping, req.SkipColumns)
		cols = importfile.KeptTargets(mapping)
		keep = importfile.KeptIndexes(mapping)
		if len(cols) == 0 {
			return nil, nil, nil, true, fmt.Errorf("文件的列与表 %s 的列没有对应关系", table)
		}
		return cols, keep, mapping, true, nil
	}
	if len(req.SkipColumns) > 0 {
		mapping := identityMapping(fileCols)
		importfile.DropSources(mapping, req.SkipColumns)
		return importfile.KeptTargets(mapping), importfile.KeptIndexes(mapping), mapping, false, nil
	}
	// No table yet: the file headers become the columns.
	return append([]string(nil), fileCols...), nil, nil, false, nil
}

// mappingNotes turns a resolved mapping into the notes the dialog shows.
func mappingNotes(fileCols []string, mapped []importfile.ColumnMap, keep []int, req ImportRequest) []string {
	var notes []string
	if len(req.ColumnMap) > 0 {
		notes = append(notes, "已应用人工列映射：未在映射中列出的源列会被跳过。")
	} else if len(req.SkipColumns) > 0 {
		notes = append(notes, "已跳过："+strings.Join(req.SkipColumns, "、")+"。")
	}
	for _, m := range mapped {
		if m.Table == "" {
			notes = append(notes, fmt.Sprintf("源列 %s 已跳过。", m.File))
			continue
		}
		if m.Table == m.File {
			continue // identity pairing, not worth a note
		}
		notes = append(notes, fmt.Sprintf("源列 %s → 表列 %s。", m.File, m.Table))
	}
	return notes
}

// importTableColumns lists a table's column names, tolerating a missing table
// (empty list, no error) because the preview uses that to decide CREATE vs map.
func importTableColumns(ctx context.Context, drv dbcore.SQLDriver, schema, table string) ([]string, error) {
	cols, err := drv.ListColumns(ctx, schema, table)
	if err == nil {
		names := make([]string, 0, len(cols))
		for _, c := range cols {
			names = append(names, c.Name)
		}
		return names, nil
	}
	// ListColumns does not have to distinguish "missing table" from a real
	// failure; ask ListTables before giving up.
	tables, terr := drv.ListTables(ctx, schema)
	if terr != nil {
		return nil, err
	}
	for _, t := range tables {
		if t.Name == table {
			return nil, err
		}
	}
	return nil, nil
}
